// ENQUIRY CAPTURE — TEMPLATE CONFIG

// ---------------------------------------------------------------- Tracking sheet
// Get the ID from:
// docs.google.com/spreadsheets/d/<THIS_PART>/edit
const TRACKER_SHEET_ID = 'YOUR_GOOGLE_SHEET_ID';
const TRACKER_TAB = 'Enquiries';

// These headings must match row 1 of the Enquiries sheet.
const COLUMNS = {
  ref:          'Ref',
  received:     'Received',
  stage:        'Stage',
  owner:        'Owner',
  owner_email:  'Owner email',
  company:      'Company',
  contact:      'Contact',
  email:        'Email',
  phone:        'Phone',
  postcode:     'Postcode',
  area:         'Area',
  premises:     'Premises',
  message:      'What they said',
  sqft:         'Sq ft',
  frequency:    'Frequency',
  access:       'Access',
  last_touch:   'Last touch',
  chases_sent:  'Chases sent',
  next_action:  'Next action',
  notes:        'Notes'
};

// ---------------------------------------------------------------- Regional routing
// Example regions and owners: replace these with your team and service areas.
// In test mode, emails are redirected to TEST_EMAIL.
const AREAS = [
  {
    area: 'North London',
    owner: 'Michael Reed',
    email: 'owner@example.com',
    postcodes: ['N', 'EN', 'HA', 'NW']
  },
  {
    area: 'South London',
    owner: 'Emily Carter',
    email: 'owner@example.com',
    postcodes: ['SW', 'SE', 'CR', 'BR']
  },
  {
    area: 'East London',
    owner: 'Daniel Brooks',
    email: 'owner@example.com',
    postcodes: ['E', 'IG', 'RM']
  },
  {
    area: 'West London',
    owner: 'Emily Carter',
    email: 'owner@example.com',
    postcodes: ['W', 'UB', 'TW']
  },
  {
    area: 'Central London',
    owner: 'Michael Reed',
    email: 'owner@example.com',
    postcodes: ['EC', 'WC']
  }
];

// Used when no postcode rule matches.
const FALLBACK = {
  area: 'Unassigned',
  owner: 'Office Team',
  email: 'office@example.com'
};

// ---------------------------------------------------------------- Mock company details
const COMPANY_NAME = 'Your Cleaning Company';
const FROM_NAME = 'Your Cleaning Team';

// Set the address that should receive customer replies.
const REPLY_TO = 'reply-to@example.com';

// Set your company contact details.
const PHONE = ''; // Add your business phone if desired.
const WEBSITE = 'https://example.com';

// ---------------------------------------------------------------- Qualification questions
const QUESTIONS = [
  'Roughly how many square feet is the space, or how many rooms and floors?',
  'How often would you like it cleaned — daily, a few times a week, weekly, or as a one-off?',
  'When can our team access the premises, and will they need keys, a fob, or an alarm code?'
];

// ---------------------------------------------------------------- Follow-up settings
const CHASE_AFTER_HOURS = 48;
const CHASE_MAX = 2;

// Leave blank because the digest workflow is not currently being configured.
const DIGEST_TO = '';
const DIGEST_ALWAYS = true;

// ---------------------------------------------------------------- Enquiry stages
const STAGE_ON_ARRIVAL = 'New';
const STAGE_AFTER_REPLY = 'Questions sent';

const OPEN_STAGES = [
  'New',
  'Questions sent',
  'Answers in',
  'Quoting',
  'Quoted'
];

// ---------------------------------------------------------------- Email safety mode
// true + email set = send every test email to your address.
// Set to false only after replacing example owner addresses and checking the recipient settings.
const TEST_RUN = true;
const TEST_EMAIL = ''; // Add an address to enable test emails; blank keeps preview mode.

const MODE = TEST_RUN !== true
  ? 'live'
  : (TEST_EMAIL.trim() !== '' ? 'test' : 'preview');

return [{
  json: {
    tracker_sheet_id: TRACKER_SHEET_ID,
    tracker_tab: TRACKER_TAB,
    columns: COLUMNS,

    areas: AREAS,
    fallback: FALLBACK,

    company_name: COMPANY_NAME,
    from_name: FROM_NAME,
    reply_to: REPLY_TO.trim(),
    phone: PHONE.trim(),
    website: WEBSITE.trim(),
    questions: QUESTIONS,

    chase_after_hours: Number(CHASE_AFTER_HOURS) || 48,
    chase_max: Number(CHASE_MAX) || 0,
    digest_to: DIGEST_TO.trim(),
    digest_always: DIGEST_ALWAYS === true,

    stage_on_arrival: STAGE_ON_ARRIVAL,
    stage_after_reply: STAGE_AFTER_REPLY,
    open_stages: OPEN_STAGES,

    mode: MODE,
    preview_only: MODE === 'preview',
    test_send: MODE === 'test',
    live_send: MODE === 'live',
    send_enabled: MODE !== 'preview',
    test_email: TEST_EMAIL.trim(),
    digest_enabled: DIGEST_TO.trim() !== ''
  }
}];

// WordPress contact forms all post slightly different field names, so rather than
// hard-coding one plugin's shape we look for the field by what it is likely to be
// called. Contact Form 7, WPForms, Gravity Forms, Elementor and Fluent Forms all land
// here cleanly, and an unknown form still gets its message through.
const cfg = $('Configure Enquiry Pipeline').first().json;

// Read the original form submission directly from the webhook.
// The Configure node outputs configuration, not the customer payload.
const raw = $('When Cleaning Enquiry Arrives').first().json || {};

// The payload might be the body itself, or wrapped in body/data/fields by the plugin.
const merge = (obj, depth) => {
  let flat = {};
  if (!obj || typeof obj !== 'object' || depth > 3) return flat;
  for (const [k, v] of Object.entries(obj)) {
    if (v && typeof v === 'object' && !Array.isArray(v)) {
      flat = Object.assign(flat, merge(v, depth + 1));
    } else {
      flat[String(k).toLowerCase().replace(/[^a-z0-9]/g, '')] = Array.isArray(v) ? v.join(', ') : v;
    }
  }
  return flat;
};
const f = merge(raw, 0);

const pick = (...names) => {
  for (const n of names) {
    const v = f[n];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
const PHONE_RE = /^[+(]?[0-9][0-9\s().-]{7,}$/;
const NAME_RE  = /^[A-Z][a-z'-]+(?: [A-Z][a-z'-]+){1,2}$/;

// Some forms post numbered fields rather than named ones - WPForms sends fields.0,
// fields.1, Gravity Forms sends input_1, input_2. Names get us nowhere there, so after
// the named lookup fails we go by the shape of the value instead.
const values = Object.entries(f)
  .map(([k, v]) => [k, String(v ?? '').trim()])
  .filter(([, v]) => v !== '');

const scan = (test, exclude) => {
  for (const [, v] of values) {
    if (exclude.includes(v)) continue;
    if (test(v)) return v;
  }
  return '';
};

let contact = pick('yourname', 'name', 'fullname', 'contactname', 'firstname');
let email   = pick('youremail', 'email', 'emailaddress', 'contactemail');
let phone   = pick('yourphone', 'phone', 'telephone', 'tel', 'mobile', 'contactnumber');
const company = pick('company', 'companyname', 'business', 'businessname', 'organisation', 'organization');
let message = pick('yourmessage', 'message', 'comments', 'enquiry', 'details', 'notes');
const premises = pick('premises', 'propertytype', 'typeofpremises', 'sitetype', 'subject', 'yoursubject');

if (!email)   email = scan((v) => EMAIL_RE.test(v), []);
if (!phone)   phone = scan((v) => PHONE_RE.test(v) && v.replace(/[^0-9]/g, '').length >= 9, [email]);
if (!contact) contact = scan((v) => NAME_RE.test(v), [email, phone, company]);
if (!message) {
  // The longest thing they typed is the message, near enough.
  const taken = [email, phone, contact, company, premises];
  message = values.map(([, v]) => v)
    .filter((v) => !taken.includes(v) && v.length > 25)
    .sort((a, b) => b.length - a.length)[0] || '';
}

// The postcode may be its own field, or buried in the message. Try the field first.
const postcodeField = pick('postcode', 'postalcode', 'zip', 'zipcode', 'address', 'siteaddress', 'location');
const UK_POSTCODE = /\b([A-Z]{1,2}[0-9][A-Z0-9]?)\s*([0-9][A-Z]{2})\b/i;
const fromField = String(postcodeField).match(UK_POSTCODE);
const fromMessage = (String(message) + ' ' + String(postcodeField)).match(UK_POSTCODE);
const found = fromField || fromMessage;
const postcode = found ? (found[1] + ' ' + found[2]).toUpperCase() : postcodeField;

// Spam gates. A honeypot field that plugins leave empty for humans, and the basics.
const honeypot = pick('honeypot', 'hp', 'website2', 'url2', 'nickname');

const problems = [];
if (honeypot) problems.push('honeypot field was filled in');
if (!EMAIL_RE.test(email)) problems.push(email ? 'email address is not valid' : 'no email address');
if (!message && !company && !contact) problems.push('nothing in the form but an address');

const now = new Date();
const stamp = now.toISOString();
// A short reference a human can read out on the phone: CE-20260831-4821
const ref = 'CE-' + stamp.slice(0, 10).replace(/-/g, '') + '-' +
  String(Math.abs(([...(email + stamp)].reduce((h, ch) => (h * 31 + ch.charCodeAt(0)) | 0, 7))) % 10000)
    .padStart(4, '0');

return [{
  json: {
    _looks_real: problems.length === 0,
    _problems: problems,
    ref,
    received: stamp,
    contact,
    email: email.toLowerCase(),
    phone,
    company: company || (contact ? contact + ' (no company given)' : ''),
    premises,
    postcode,
    message,
    _raw_field_names: Object.keys(f).slice(0, 40)
  }
}];

// Not a real enquiry. It is dropped here rather than reaching the sheet, but the
// reason is kept so you can see in the execution list why.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, {
    _outcome: 'rejected',
    _reason: (i.json._problems || []).join('; ') || 'did not look like an enquiry'
  })
}));

// Match the postcode against the areas in config, longest prefix first, so a rule for
// 'SW1' beats a rule for 'SW'. No match, or no postcode, and it goes to the fallback -
// never nowhere.
const cfg = $('Configure Enquiry Pipeline').first().json;
const enquiry = $input.first().json;

const tidy = String(enquiry.postcode || '').toUpperCase().replace(/[^A-Z0-9]/g, '');

let best = null;
let bestLength = 0;

for (const area of cfg.areas || []) {
  for (const prefix of area.postcodes || []) {
    const p = String(prefix).toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (p && tidy.startsWith(p) && p.length > bestLength) {
      best = area;
      bestLength = p.length;
    }
  }
}

const chosen = best || cfg.fallback || {};
const ownerEmail = String(chosen.email || '').trim();

return [{
  json: Object.assign({}, enquiry, {
    area: chosen.area || 'Unassigned',
    owner: chosen.owner || 'Office',
    owner_email: ownerEmail,
    _matched_on: best ? tidy.slice(0, bestLength) : '',
    _owner_has_email: ownerEmail !== '',
    stage: cfg.stage_on_arrival
  })
}];

// Lightweight lead scoring keeps urgent or information-rich enquiries visible.
// It is deliberately rule-based so the result is fast, explainable, and costs nothing.
const e = $input.first().json;
const text = [e.message, e.premises, e.company].filter(Boolean).join(' ').toLowerCase();

let score = 0;
const reasons = [];

if (String(e.company || '').trim()) { score += 1; reasons.push('company supplied'); }
if (String(e.phone || '').trim()) { score += 1; reasons.push('phone supplied'); }
if (String(e.message || '').trim().length >= 120) { score += 2; reasons.push('detailed brief'); }
if (/urgent|asap|immediately|this week|emergency/.test(text)) { score += 3; reasons.push('urgent timing'); }
if (/office|warehouse|school|hotel|restaurant|medical|clinic|multiple|daily/.test(text)) { score += 2; reasons.push('commercial scope'); }
if (!String(e.postcode || '').trim()) { score -= 1; reasons.push('postcode missing'); }

const priority = score >= 6 ? 'Urgent' : score >= 4 ? 'High' : score >= 2 ? 'Normal' : 'Low';

return [{ json: Object.assign({}, e, { lead_score: score, priority, priority_reasons: reasons }) }];

// The acknowledgement, and the internal heads-up that goes with it. Plain, quick to
// read on a phone, and it asks the three questions so the next email from them has
// everything needed to quote.
const cfg = $('Configure Enquiry Pipeline').first().json;
const e = $input.first().json;

const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const firstName = String(e.contact || '').trim().split(/\s+/)[0];
const greeting = firstName && /^[A-Za-z'-]{2,}$/.test(firstName) ? 'Hi ' + firstName + ',' : 'Hello,';

const INK = '#1b1d21', MUTED = '#5c6470', LINE = '#e4e7eb', ACCENT = '#1a6b4a';
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const p = (html, extra) => '<p style="margin:0 0 16px;font:400 15px/1.6 ' + FONT +
  ';color:' + INK + ';' + (extra || '') + '">' + html + '</p>';

const questionsHtml = '<ol style="margin:0 0 18px;padding-left:20px;font:400 15px/1.7 ' + FONT +
  ';color:' + INK + '">' +
  (cfg.questions || []).map((q) => '<li style="margin:0 0 8px">' + esc(q) + '</li>').join('') +
  '</ol>';

const signOff = [
  cfg.company_name,
  cfg.phone ? 'Tel ' + cfg.phone : '',
  cfg.website
].filter(Boolean);

const customerSubject = 'Thanks for your enquiry — a few quick questions (' + e.ref + ')';

const customerHtml =
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f6f7f8;margin:0;padding:24px 12px"><tr><td align="center">' +
  '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="580" style="max-width:580px;width:100%;background:#ffffff;border:1px solid ' + LINE + ';border-radius:10px">' +
  '<tr><td style="padding:28px 30px">' +
  p('<strong style="font-size:16px">' + esc(cfg.company_name) + '</strong>', 'margin-bottom:22px;color:' + MUTED) +
  p(esc(greeting)) +
  p('Thanks for getting in touch. Your enquiry is with ' + esc(e.owner) +
    ', who looks after ' + esc(e.area) + ', and we have it logged as <strong>' + esc(e.ref) + '</strong>.') +
  p('So we can put a proper price together rather than a vague one, could you answer these three?') +
  questionsHtml +
  p('Reply to this email and it comes straight back to us. Once we have those answers we will send a written quote.') +
  p(signOff.map(esc).join('<br>'), 'margin-top:24px;color:' + MUTED + ';font-size:14px') +
  '</td></tr></table></td></tr></table>';

const customerText = [
  greeting, '',
  'Thanks for getting in touch. Your enquiry is with ' + e.owner + ', who looks after ' +
    e.area + ', and we have it logged as ' + e.ref + '.', '',
  'So we can put a proper price together rather than a vague one, could you answer these three?', ''
].concat((cfg.questions || []).map((q, i) => (i + 1) + '. ' + q))
 .concat(['',
  'Reply to this email and it comes straight back to us. Once we have those answers we',
  'will send a written quote.', ''
 ]).concat(signOff).join('\n');

// The internal note. Everything needed to act, nothing else.
const ownerSubject = '[' + e.area + '] New enquiry — ' + (e.company || e.contact || e.email) +
  ' (' + e.ref + ')';

const rows = [
  ['Company', e.company], ['Contact', e.contact], ['Email', e.email], ['Phone', e.phone],
  ['Postcode', e.postcode], ['Area', e.area], ['Premises', e.premises]
].filter(([, v]) => String(v || '').trim() !== '');

const ownerHtml =
  '<div style="font:400 15px/1.6 ' + FONT + ';color:' + INK + '">' +
  '<p style="margin:0 0 14px"><strong>' + esc(e.ref) + '</strong> — yours to quote. ' +
  'The customer already has the three standard questions.</p>' +
  '<table cellpadding="0" cellspacing="0" border="0" style="margin:0 0 16px">' +
  rows.map(([k, v]) => '<tr><td style="padding:3px 16px 3px 0;color:' + MUTED + '">' + esc(k) +
    '</td><td style="padding:3px 0">' + esc(v) + '</td></tr>').join('') +
  '</table>' +
  (e.message ? '<p style="margin:0 0 6px;color:' + MUTED + '">What they wrote</p>' +
    '<div style="padding:12px 14px;background:#f6f7f8;border-left:3px solid ' + ACCENT +
    ';white-space:pre-wrap">' + esc(e.message) + '</div>' : '') +
  '</div>';

const ownerText = [
  e.ref + ' — yours to quote. The customer already has the three standard questions.', ''
].concat(rows.map(([k, v]) => k + ': ' + v))
 .concat(e.message ? ['', 'What they wrote:', e.message] : []).join('\n');

return [{
  json: Object.assign({}, e, {
    // In preview mode no reply actually goes out, so the sheet must not claim one did.
    stage: cfg.send_enabled ? cfg.stage_after_reply : cfg.stage_on_arrival,
    customer_subject: customerSubject,
    customer_html: customerHtml,
    customer_text: customerText,
    owner_subject: ownerSubject,
    owner_html: ownerHtml,
    owner_text: ownerText
  })
}];

// One row, in the same shape every time. Written before any email goes out, so an
// enquiry can never be lost to a mail failure.
const cfg = $('Configure Enquiry Pipeline').first().json;
const C = cfg.columns;
const e = $input.first().json;

const row = {};
row[C.ref]         = e.ref;
row[C.received]    = e.received.slice(0, 16).replace('T', ' ');
row[C.stage]       = e.stage;
row[C.owner]       = e.owner;
row[C.owner_email] = e.owner_email;
row[C.company]     = e.company;
row[C.contact]     = e.contact;
row[C.email]       = e.email;
row[C.phone]       = e.phone;
row[C.postcode]    = e.postcode;
row[C.area]        = e.area;
row[C.premises]    = e.premises;
row[C.message]     = String(e.message || '').slice(0, 4000);
row[C.sqft]        = '';
row[C.frequency]   = '';
row[C.access]      = '';
row[C.last_touch]  = e.received.slice(0, 16).replace('T', ' ');
row[C.chases_sent] = 0;
row[C.next_action] = 'Waiting on their answers';
row[C.notes]       = '';

return [{ json: row }];

// PREVIEW mode: the row is in the sheet but no email is sent. Open this node's output
// to read exactly what the customer and the owner would have received.
return $input.all().map((i) => ({
  json: Object.assign({}, i.json, { _outcome: 'preview', _would_email: i.json.email })
}));

// Return one stable response shape to the website, regardless of which branch ran.
const enquiry = $('Parse Form Fields').first().json;
const cfg = $('Configure Enquiry Pipeline').first().json;

let status = 'accepted';
let ok = true;
let message = 'Thanks — your enquiry has been received.';

if (!enquiry._looks_real) {
  status = 'rejected';
  ok = false;
  message = 'Please check the required details and submit the form again.';
} else if (cfg.preview_only) {
  status = 'preview';
  message = 'Preview completed. The enquiry was logged and no emails were sent.';
}

return [{ json: { response: { ok, status, ref: enquiry.ref, message } } }];
